{% set company = frappe.get_doc('Company', doc.company) %}
{% set currency = frappe.db.get_value('Currency', doc.currency, 'symbol') or doc.currency or 'YER' %}
{% set branding_logo = frappe.db.get_single_value('POS Branding Settings', 'primary_logo') if frappe.db.exists('DocType', 'POS Branding Settings') else '' %}
{% set logo = company.company_logo or branding_logo or '' %}
{% set issue_time = (doc.posting_time|string).split('.')[0] if doc.posting_time else '' %}
{% set outstanding = doc.outstanding_amount or 0 %}
{% set customer_debt = frappe.db.sql("select coalesce(sum(outstanding_amount), 0) from `tabSales Invoice` where customer=%s and company=%s and docstatus=1", (doc.customer, doc.company))[0][0] if doc.customer else 0 %}
<style>
@font-face{font-family:CairoPOS;src:url('/assets/pos_next/fonts/Cairo-Variable.ttf') format('truetype');font-weight:200 1000;}@page{size:A4;margin:10mm;}*{box-sizing:border-box}body{background:#fff;color:#16263a;font-family:CairoPOS,'DejaVu Sans',sans-serif;font-size:11px;line-height:1.75}.invoice{direction:rtl;max-width:820px;margin:0 auto}.hero{background:linear-gradient(135deg,#075e54,#0f766e);border-radius:18px 18px 0 0;color:#fff;display:flex;align-items:center;justify-content:space-between;padding:25px 29px}.brand{display:flex;align-items:center;gap:15px}.logo{background:#fff;border-radius:12px;max-height:64px;max-width:135px;object-fit:contain;padding:6px}.brand h1{font-size:24px;line-height:1.25;margin:0}.brand p{color:#d1fae5;font-size:10px;margin:5px 0 0}.badge{border:1px solid #99f6e4;border-radius:12px;padding:7px 14px;text-align:center}.badge b,.badge small{display:block}.badge small{color:#ccfbf1;font-size:9px}.paper{border:1px solid #d7e5e2;border-radius:0 0 18px 18px;padding:23px 28px 27px}.meta{display:grid;gap:11px;grid-template-columns:repeat(2,1fr);margin-bottom:15px}.card{background:#f6fbfa;border:1px solid #dfedeb;border-radius:10px;padding:10px 12px}.label{color:#617084;display:block;font-size:9px;margin-bottom:3px}.value{direction:ltr;font-weight:800}.customer{align-items:center;background:#fefce8;border:1px solid #fde68a;border-radius:12px;display:flex;justify-content:space-between;margin:0 0 18px;padding:12px 14px}.customer strong{font-size:13px}.muted{color:#64748b;font-size:10px}.status{border-radius:8px;font-size:10px;font-weight:800;padding:5px 9px}.paid{background:#dcfce7;color:#166534}.due{background:#fee2e2;color:#b91c1c}.debt{background:#fff1f2;border:1px solid #fecdd3;border-radius:11px;color:#9f1239;margin:0 0 18px;padding:12px 14px}.debt strong{display:block;font-size:15px;margin-top:2px}.table{border-collapse:separate;border-spacing:0;width:100%}.table th{background:#075e54;color:#fff;font-size:10px;padding:10px 9px;text-align:right}.table th:first-child{border-radius:0 8px 8px 0}.table th:last-child{border-radius:8px 0 0 8px}.table td{border-bottom:1px solid #e7efed;padding:11px 9px;vertical-align:top}.table tr:nth-child(even) td{background:#fbfdfd}.amount{direction:ltr;font-weight:800;text-align:left;white-space:nowrap}.serial{color:#0f766e;direction:ltr;font-family:monospace;font-size:10px;margin-top:3px}.discount{color:#b45309;font-size:10px;margin-top:3px}.summary{display:grid;gap:17px;grid-template-columns:1fr 305px;margin-top:21px}.panel{border:1px solid #deece9;border-radius:12px;padding:14px}.panel h3{color:#075e54;font-size:12px;margin:0 0 8px}.line{align-items:center;display:flex;justify-content:space-between;gap:12px;padding:5px 0}.line+.line{border-top:1px solid #edf2f2}.total{background:#ecfdf5;border:1px solid #a7f3d0;border-radius:9px;color:#065f46;font-size:16px;font-weight:900;margin-top:9px;padding:10px}.footer{border-top:1px dashed #bed0cc;color:#64748b;font-size:10px;margin-top:23px;padding-top:14px}.footer b{color:#075e54;display:block;font-size:15px;margin-bottom:2px}@media(max-width:600px){.hero,.customer{align-items:flex-start;flex-direction:column;gap:12px}.meta,.summary{grid-template-columns:1fr}.table{font-size:9px}}
</style>
<div class='invoice'><header class='hero'><div class='brand'>{% if logo %}<img class='logo' src='{{ logo }}' alt='{{ company.company_name or doc.company }}'>{% endif %}<div><h1>{{ company.company_name or doc.company }}</h1><p>{% if company.phone_no %}{{ company.phone_no }}{% endif %}{% if company.phone_no and company.website %} · {% endif %}{% if company.website %}{{ company.website }}{% endif %}</p></div></div><div class='badge'><b>{% if doc.is_return %}إشعار مرتجع{% else %}فاتورة مبيعات{% endif %}</b><small>{% if doc.is_return %}RETURN NOTE{% else %}SALES INVOICE{% endif %}</small></div></header><main class='paper'><section class='meta'><div class='card'><span class='label'>رقم الفاتورة</span><span class='value'>{{ doc.name }}</span></div><div class='card'><span class='label'>تاريخ ووقت الإصدار</span><span class='value'>{{ doc.posting_date }}{% if issue_time %} · {{ issue_time }}{% endif %}</span></div></section><section class='customer'><div><span class='label'>العميل</span><strong>{{ doc.customer_name or doc.customer or 'عميل نقدي' }}</strong>{% if doc.contact_mobile %}<span class='muted'> · {{ doc.contact_mobile }}</span>{% endif %}</div><span class='status {% if outstanding > 0 %}due{% else %}paid{% endif %}'>{% if outstanding > 0 %}بيع آجل — متبقي لهذه الفاتورة {{ '%.2f'|format(outstanding) }} {{ currency }}{% else %}مدفوعة بالكامل{% endif %}</span></section>{% if outstanding > 0 %}<section class='debt'><span>الرصيد الإجمالي المستحق على العميل بعد هذه الفاتورة</span><strong>{{ '%.2f'|format(customer_debt) }} {{ currency }}</strong><span class='muted'>يشمل هذه الفاتورة وأي فواتير آجلة سابقة غير مسددة.</span></section>{% endif %}<table class='table'><thead><tr><th>الصنف</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>{% for item in doc.items %}<tr><td><strong>{{ item.item_name }}</strong>{% if item.item_code and item.item_code != item.item_name %}<div class='muted'>{{ item.item_code }}</div>{% endif %}{% if item.serial_no %}<div class='serial'>IMEI / S/N: {{ item.serial_no|replace('\n', ', ') }}</div>{% endif %}{% if item.discount_amount %}<div class='discount'>خصم الصنف: {{ '%.2f'|format(item.discount_amount) }} {{ currency }}</div>{% endif %}</td><td class='amount'>{{ '%.2f'|format(item.qty or 0) }} {{ item.uom or '' }}</td><td class='amount'>{{ '%.2f'|format(item.rate or 0) }} {{ currency }}</td><td class='amount'>{{ '%.2f'|format(item.amount or 0) }} {{ currency }}</td></tr>{% endfor %}</tbody></table><section class='summary'><div class='panel'><h3>تفاصيل السداد</h3>{% if doc.payments %}{% for payment in doc.payments if payment.amount %}<div class='line'><span>{{ payment.mode_of_payment }}</span><strong class='amount'>{{ '%.2f'|format(payment.amount) }} {{ currency }}</strong></div>{% endfor %}{% else %}<div class='muted'>لم يتم تسجيل دفعة لهذه الفاتورة.</div>{% endif %}{% if doc.change_amount %}<div class='line'><span>المبلغ المعاد للعميل</span><strong class='amount'>{{ '%.2f'|format(doc.change_amount) }} {{ currency }}</strong></div>{% endif %}</div><div class='panel'><h3>ملخص الفاتورة</h3><div class='line'><span>إجمالي الأصناف</span><strong class='amount'>{{ '%.2f'|format(doc.total or 0) }} {{ currency }}</strong></div>{% if doc.discount_amount %}<div class='line'><span>خصم الفاتورة</span><strong class='amount'>- {{ '%.2f'|format(doc.discount_amount) }} {{ currency }}</strong></div>{% endif %}<div class='line total'><span>الإجمالي المستحق</span><span class='amount'>{{ '%.2f'|format(doc.grand_total or 0) }} {{ currency }}</span></div></div></section><footer class='footer'><b>شكرًا لثقتكم بنا</b>هذه نسخة إلكترونية من الفاتورة. احتفظ بها للرجوع إليها عند الحاجة.</footer></main></div>
